def transform(grid):
    """Extend a lone horizontal foreground segment to the right edge with 1s."""
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        fg = [c for c, value in enumerate(row) if value != bg]
        if not fg:
            continue
        # A single contiguous foreground segment with a background tail is the
        # trace to continue; fragmented rows and lines reaching the edge stay.
        left, right = min(fg), max(fg)
        if len(fg) == right - left + 1 and right < len(row) - 1:
            for c in range(right + 1, len(row)):
                out[r][c] = 1
    return out
